mapper.update:
update member_cash_withdraw
   set balance_deduct_id = #{balanceDeductId}
 where id = #{id} and member_id = #{memberId} and amount = #{amount}
   and out_batch_no = #{outBatchNo} and out_detail_no = #{outDetailNo}
   and balance_deduct_id is null and balance_refund_id is null and status = 0
   and del_flag = 0 and (frozen is null or frozen = 0)
   and exists (select 1 from member_cash_withdraw_fund_fact f
                where f.id = #{balanceDeductId} and f.withdrawal_id = #{id} and f.kind = 'DEBIT'
                  and f.member_id = #{memberId} and f.amount = #{amount}
                  and f.out_batch_no = #{outBatchNo} and f.out_detail_no = #{outDetailNo})

update member_cash_withdraw
   set status = 1, finish_time = #{finishTime}, last_query_time = #{lastQueryTime}
    , wechat_batch_status = #{wechatBatchStatus}
    , wechat_detail_id = #{wechatDetailId}
 where id = #{id} and status in (0, 3, 4) and balance_refund_id is null
   and del_flag = 0 and (frozen is null or frozen = 0)

update member_cash_withdraw
out_batch_no = coalesce(out_batch_no, #{outBatchNo}), out_detail_no = coalesce(out_detail_no, #{outDetailNo}), transfer_batch_id = #{transferBatchId}, wechat_detail_id = #{wechatDetailId}, status = #{status}, fail_reason = #{failReason}, channel_error_code = #{channelErrorCode}, finish_time = #{finishTime}, wechat_batch_status = #{wechatBatchStatus}, submit_time = #{submitTime}, last_query_time = #{lastQueryTime}, manual_operator = #{manualOperator}, manual_verifier = #{manualVerifier}, manual_note = #{manualNote}, trace_id = #{traceId}, audit_by = #{auditBy}, audit_time = #{auditTime},
where id = #{id}

mapper.select:
select  from member_cash_withdraw
where del_flag = 0 and member_id = #{memberId}
order by create_time desc

select id from member_cash_withdraw
where del_flag = 0 and status = 0 and coalesce(submit_time, create_time) < #{before}
order by id asc limit 20

select  from member_cash_withdraw
where del_flag = 0
 and status = #{status}
 and member_id = #{memberId}
order by create_time desc

