update member_cash_withdraw
status = #{status}, balance_refund_id = #{balanceRefundId}, manual_verifier = #{manualVerifier}, manual_note = #{manualNote}, finish_time = #{finishTime}, audit_by = #{auditBy}, audit_time = #{auditTime},
where id = #{id} and status = 4 and (frozen is null or frozen = 0) and manual_operator is not null and manual_operator != #{manualVerifier}
